/* From Uiverse.io by TemRevil  - Tags:  */
.__UIV_SCOPE__ .input-wrapper {
  position: relative;
  display: flex;
  align-items: center;
}

.__UIV_SCOPE__ .input {
  min-width: 300px;
  padding: 20px 40px 20px 60px;
  background: #14213d;
  color: #fff;
  font-size: 24px;
  font-weight: 400;
  outline: none;
  border: none;
  border-radius: 8px;
  box-shadow: 60px 40px 80px 0px #2d00f75b, -100px -40px 100px #db00b65b,
    inset -40px -20px 1000px -150px #db00b65b,
    inset 40px 20px 1000px -160px #2d00f7;
  transition: 0.2s 0s ease-in-out;
}

.__UIV_SCOPE__ .input::placeholder {
  color: #f0f8ff9c;
  font-size: 20px;
}

.__UIV_SCOPE__ .input:hover,
.__UIV_SCOPE__ .input:focus {
  background: #dfe7fd;
  box-shadow: -100px -40px 100px 30px #2d00f75b, 60px 40px 100px 5px #db00b65b,
    inset 40px 20px 1000px -150px #f20089,
    inset -40px -20px 1000px -160px #2d00f7;
}

.__UIV_SCOPE__ .search-icon {
  width: 30px;
  height: 30px;
  position: absolute;
  left: 20px;
  top: 50%;
  transform: translateY(-50%) scale(0.8);
  fill: #fff;
  stroke: #fff;
}

.__UIV_SCOPE__ .filter-icon {
  width: 30px;
  height: 30px;
  position: absolute;
  right: 20px;
  top: 50%;
  transform: translateY(-50%) scale(0.8);
  fill: #fff;
  stroke: #fff;
  cursor: pointer;
  transition: 0.15s 0s ease-in-out;
}
.__UIV_SCOPE__ .filter-icon:active {
  scale: 0.9;
}

.__UIV_SCOPE__ .input:hover.search-icon,
.__UIV_SCOPE__ .input:focus.search-icon,
.__UIV_SCOPE__ .input:hover.filter-icon,
.__UIV_SCOPE__ .input:focus.filter-icon {
  fill: #14213d;
  stroke: #14213d;
}
